import{_ as e,c as t,o as a,a4 as n}from"./chunks/framework.ttppV29E.js";const i="/assets/create-agent-dialog-settings.DPL2RzyQ.png",o="/assets/create-agent-dialog-configuration.CZQL3fYa.png",r="/assets/create-agent-dialog-skill.BSvSS5-x.png",s="/assets/create-agent-dialog-mcp.CdwZtIy0.png",l="/assets/agent-default-version-menu.BHctQvw3.png",d="/assets/agent-default-version-dialog.D23LHLKP.png",x=JSON.parse('{"title":"Creating an Agent","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/creating.md","filePath":"docs/agents/creating.md","lastUpdated":1786714481000}'),h={name:"docs/agents/creating.md"},c=n('<h1 id="creating-an-agent" tabindex="-1">Creating an Agent <a class="header-anchor" href="#creating-an-agent" aria-label="Permalink to &quot;Creating an Agent&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before creating an agent, you need:</p><ul><li>The <code>create:AgentConfiguration</code> permission claim</li><li>Agents enabled for your tenant - contact support if it isn&#39;t</li><li>At least one MCP server configured if you want the agent to invoke tools (see <a href="./../mcp-servers/">MCP Servers</a>)</li></ul><h2 id="create-a-new-agent" tabindex="-1">Create a New Agent <a class="header-anchor" href="#create-a-new-agent" aria-label="Permalink to &quot;Create a New Agent&quot;">​</a></h2><ol><li>Navigate to <strong>AI Tools &gt; Agents</strong></li><li>Click the <strong>Create</strong> button in the top-right corner</li><li>The agent editor dialog opens with four tabs: <strong>Agent settings</strong>, <strong>Configuration</strong>, <strong>Skill configuration</strong>, <strong>MCP servers</strong></li></ol><h2 id="agent-settings-tab" tabindex="-1">Agent Settings Tab <a class="header-anchor" href="#agent-settings-tab" aria-label="Permalink to &quot;Agent Settings Tab&quot;">​</a></h2><p><img src="'+i+'" alt="agents"></p><h3 id="agent-name" tabindex="-1">Agent Name <a class="header-anchor" href="#agent-name" aria-label="Permalink to &quot;Agent Name&quot;">​</a></h3><p><strong>Required.</strong> The unique name for your agent. This value is used in the connection URL, so choose something meaningful and URL-friendly.</p><ul><li>Letters, numbers, and hyphens only</li><li>Must be unique across your tenant</li><li>Cannot be changed after creation</li></ul><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Optional. Describes what this agent does. This text is published in the agent&#39;s A2A discovery card so calling agents understand its purpose.</p><h3 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h3><p><strong>Required.</strong> A semantic version number in the format <code>X.Y.Z</code> (e.g. <code>1.0.0</code>). Each agent must have at least one version. Versions must be unique within the agent.</p><h3 id="execution-timeout" tabindex="-1">Execution Timeout <a class="header-anchor" href="#execution-timeout" aria-label="Permalink to &quot;Execution Timeout&quot;">​</a></h3><p>Maximum time (in seconds) the agent has to complete a task. Range 1–600. Defaults to 300.</p><h3 id="temperature" tabindex="-1">Temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Temperature&quot;">​</a></h3><p>LLM sampling temperature in the range 0–1. Lower values make the agent more deterministic. Defaults to 0.1.</p><h3 id="set-as-default-version" tabindex="-1">Set as Default Version <a class="header-anchor" href="#set-as-default-version" aria-label="Permalink to &quot;Set as Default Version&quot;">​</a></h3><p>When checked, this version is exposed by default when an A2A client requests the agent&#39;s card without specifying a version.</p><h2 id="configuration-tab" tabindex="-1">Configuration Tab <a class="header-anchor" href="#configuration-tab" aria-label="Permalink to &quot;Configuration Tab&quot;">​</a></h2><p><img src="'+o+'" alt="agents"></p><h3 id="instructions" tabindex="-1">Instructions <a class="header-anchor" href="#instructions" aria-label="Permalink to &quot;Instructions&quot;">​</a></h3><p>The system prompt provided to the LLM when the agent is invoked. Up to 8000 characters. Tells the agent how to behave, what tone to take, and how to use its tools.</p><h3 id="default-input-modes-default-output-modes" tabindex="-1">Default Input Modes / Default Output Modes <a class="header-anchor" href="#default-input-modes-default-output-modes" aria-label="Permalink to &quot;Default Input Modes / Default Output Modes&quot;">​</a></h3><p>MIME types the agent advertises in its A2A card as supported inputs and outputs. Defaults to <code>application/json</code>. Press Enter to add a value.</p><h2 id="skill-configuration-tab" tabindex="-1">Skill Configuration Tab <a class="header-anchor" href="#skill-configuration-tab" aria-label="Permalink to &quot;Skill Configuration Tab&quot;">​</a></h2><p><img src="'+r+'" alt="agents"></p><p>Skills describe what the agent can do. They are advertised on the agent card so other agents can discover and decide whether to delegate work.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Skills are descriptive only. They do not directly map to executable code. The actual work is performed by the LLM using the configured MCP server tools, guided by the agent&#39;s instructions.</p></div><p>You can add multiple skills - Click <strong>Done</strong> to add more.</p><h3 id="skill-id" tabindex="-1">Skill ID <a class="header-anchor" href="#skill-id" aria-label="Permalink to &quot;Skill ID&quot;">​</a></h3><p><strong>Required.</strong> Kebab-case identifier (e.g. <code>assess-eligibility</code>). Visible in the public agent card and used by callers to reference the skill.</p><h3 id="skill-name" tabindex="-1">Skill Name <a class="header-anchor" href="#skill-name" aria-label="Permalink to &quot;Skill Name&quot;">​</a></h3><p><strong>Required.</strong> Display name for this skill.</p><h3 id="description-1" tabindex="-1">Description <a class="header-anchor" href="#description-1" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>Free text describing what the skill does and when to use it. The quality of this text directly affects how well calling agents pick the right skill.</p><h3 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h3><p>Optional list of tags that help categorise and discover the skill.</p><h2 id="mcp-servers-tab" tabindex="-1">MCP Servers Tab <a class="header-anchor" href="#mcp-servers-tab" aria-label="Permalink to &quot;MCP Servers Tab&quot;">​</a></h2><p><img src="'+s+'" alt="agents"></p><p>Register the MCP servers that provide the tools the agent will use. All tools from all registered servers are available to the LLM at runtime.</p><h3 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP Server&quot;">​</a></h3><p>Select an existing MCP server configuration from your account.</p><h3 id="version-1" tabindex="-1">Version <a class="header-anchor" href="#version-1" aria-label="Permalink to &quot;Version&quot;">​</a></h3><p>Choose a specific version of the MCP server, or <strong>Default</strong> to use whichever version is set as the server&#39;s default.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>An agent with no MCP servers can still respond, but only based on its instructions and the contents of the prompt - it has no tools to call.</p></div><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><p>Click <strong>Save changes</strong> to create the agent. The agent appears in the list and is immediately available to A2A clients (provided both the agent and version are active).</p><h2 id="editing-an-existing-agent" tabindex="-1">Editing an Existing Agent <a class="header-anchor" href="#editing-an-existing-agent" aria-label="Permalink to &quot;Editing an Existing Agent&quot;">​</a></h2><ol><li>Click the three-dot menu on the agent row and select <strong>Edit</strong></li><li>The edit dialog opens with the same tabs. The agent name cannot be changed after creation.</li></ol><p>To edit a specific version, expand the agent in the list and click the three-dot menu on the version row.</p><h3 id="agent-actions-menu" tabindex="-1">Agent Actions Menu <a class="header-anchor" href="#agent-actions-menu" aria-label="Permalink to &quot;Agent Actions Menu&quot;">​</a></h3><p>The three-dot menu on the agent row provides the following options:</p><table><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td>Edit</td><td>Open the agent editor dialog</td></tr><tr><td>Copy URL</td><td>Copy the A2A connection URL to the clipboard</td></tr><tr><td>Set Default Version</td><td>Open a dialog to change which version is exposed by default</td></tr><tr><td>Delete</td><td>Delete the agent (with confirmation)</td></tr></tbody></table><h3 id="version-actions-menu" tabindex="-1">Version Actions Menu <a class="header-anchor" href="#version-actions-menu" aria-label="Permalink to &quot;Version Actions Menu&quot;">​</a></h3><p>The three-dot menu on a version row provides:</p><table><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td>Edit version</td><td>Open the editor for this specific version</td></tr><tr><td>Add version</td><td>Create a new version on this agent</td></tr></tbody></table><h2 id="setting-the-default-version" tabindex="-1">Setting the Default Version <a class="header-anchor" href="#setting-the-default-version" aria-label="Permalink to &quot;Setting the Default Version&quot;">​</a></h2><p>The default version is the one returned in the agent card when no version is specified. Set it during creation via the <strong>Set as default version</strong> checkbox, or after creation via the agent&#39;s three-dot menu.</p><p><img src="'+l+'" alt="agents"><img src="'+d+'" alt="agents"></p><h2 id="activating-and-deactivating" tabindex="-1">Activating and Deactivating <a class="header-anchor" href="#activating-and-deactivating" aria-label="Permalink to &quot;Activating and Deactivating&quot;">​</a></h2><h3 id="agent-level" tabindex="-1">Agent Level <a class="header-anchor" href="#agent-level" aria-label="Permalink to &quot;Agent Level&quot;">​</a></h3><p>Toggle the <strong>Active</strong> switch on the agent row to enable or disable the entire agent. A deactivated agent rejects all A2A client connections.</p><h3 id="version-level" tabindex="-1">Version Level <a class="header-anchor" href="#version-level" aria-label="Permalink to &quot;Version Level&quot;">​</a></h3><p>Toggle the <strong>Active</strong> switch on a version row to enable or disable that version. Inactive versions are excluded from the default version fallback.</p><h2 id="warning-indicators" tabindex="-1">Warning Indicators <a class="header-anchor" href="#warning-indicators" aria-label="Permalink to &quot;Warning Indicators&quot;">​</a></h2><p>The agent list displays warning icons when a version references an MCP server that no longer exists. The tooltip lists the missing server names. Resolve them by editing the version to add or fix MCP server references.</p>',69),g=[c];function u(p,m,b,f,v,k){return a(),t("div",null,g)}const P=e(h,[["render",u]]);export{x as __pageData,P as default};
